import { spawnSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import type { ExtensionAPI, SessionEntry } from "@mariozechner/pi-coding-agent";
import type { AssistantMessage } from "@mariozechner/pi-ai";

function getLastAssistantText(branch: SessionEntry[]): string | undefined {
    for (let i = branch.length - 1; i >= 0; i--) {
        const entry = branch[i];
        if (entry.type !== "message") {
            continue;
        }
        const message = entry.message;
        if (message.role !== "assistant") {
            continue;
        }
        const assistant = message as AssistantMessage;
        if (assistant.stopReason !== "stop") {
            return undefined;
        }
        const text = assistant.content
            .filter((part): part is { type: "text"; text: string } => part.type === "text")
            .map((part) => part.text)
            .join("\n")
            .trim();
        return text || undefined;
    }
    return undefined;
}

function formatQuotedEditorText(text: string): string {
    return text
        .split("\n")
        .map((line) => `> ${line}`)
        .join("\n");
}

function editWithExternalEditor(initialText: string): string {
    const editorCmd = process.env.VISUAL || process.env.EDITOR;
    if (!editorCmd) {
        throw new Error("No editor configured. Set $VISUAL or $EDITOR environment variable.");
    }

    const tmpFile = path.join(os.tmpdir(), `pi-comment-${Date.now()}.md`);
    try {
        fs.writeFileSync(tmpFile, initialText, "utf-8");
        const [editor, ...editorArgs] = editorCmd.split(" ");
        const result = spawnSync(editor, [...editorArgs, tmpFile], {
            stdio: "inherit",
            shell: process.platform === "win32",
        });
        if (result.status !== 0) {
            throw new Error(`Editor exited with status ${result.status ?? "unknown"}`);
        }
        return fs.readFileSync(tmpFile, "utf-8").replace(/\n$/, "");
    } finally {
        try {
            fs.unlinkSync(tmpFile);
        } catch {
            // Ignore cleanup errors
        }
    }
}

export default function (pi: ExtensionAPI) {
    pi.registerCommand("comment", {
        description: "Open the last assistant message in $EDITOR and load the result into the editor",
        handler: async (_args, ctx) => {
            if (!ctx.hasUI) {
                ctx.ui.notify("comment requires interactive mode", "error");
                return;
            }

            const lastAssistantText = getLastAssistantText(ctx.sessionManager.getBranch());
            if (!lastAssistantText) {
                ctx.ui.notify("No completed assistant message found on the current branch", "error");
                return;
            }

            try {
                const editedText = editWithExternalEditor(formatQuotedEditorText(lastAssistantText));
                ctx.ui.setEditorText(editedText);
                ctx.ui.notify("Loaded edited quoted assistant text into the editor", "info");
            } catch (error) {
                ctx.ui.notify(error instanceof Error ? error.message : String(error), "error");
            }
        },
    });
}

import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
import * as fs from "node:fs/promises";
import * as path from "node:path";

interface PlanState {
  enabled: boolean;
  planFile: string;
  steps: Array<{
    id: string;
    description: string;
    status: "pending" | "in-progress" | "completed" | "skipped";
    timestamp: number;
  }>;
  currentStep: number;
}

async function resolvePlanFile(): Promise<string> {
  try {
    await fs.access(".specify");
    await fs.mkdir(".specify/scratch", { recursive: true });
    return ".specify/scratch/PLAN.md";
  } catch {
    return "PLAN.md";
  }
}

export default function (pi: ExtensionAPI) {
  const planState: PlanState = {
    enabled: false,
    planFile: "PLAN.md",
    steps: [],
    currentStep: 0,
  };

  async function savePlan() {
    const content = `# Plan

**Status**: ${planState.enabled ? "Active" : "Inactive"}
**Last Updated**: ${new Date().toISOString()}

## Steps

${planState.steps
  .map(
    (step, i) => `### ${i + 1}. ${step.description}
- **Status**: ${step.status}
- **ID**: ${step.id}
`
  )
  .join("\n")}
`;
    await fs.mkdir(path.dirname(planState.planFile), { recursive: true }).catch(() => {});
    fs.writeFile(planState.planFile, content).catch(console.error);
  }

  function generateId() {
    return Math.random().toString(36).substring(2, 9);
  }

  pi.registerCommand("plan", {
    description: "Toggle plan mode or manage plan steps",
    handler: async (args, ctx) => {
      const [cmd, ...rest] = args?.split(" ") || [];

      switch (cmd) {
        case "start":
          planState.enabled = true;
          planState.steps = [];
          planState.currentStep = 0;
          planState.planFile = await resolvePlanFile();
          await savePlan();
          ctx.ui.notify(`Plan mode: ON  (file: ${planState.planFile})`, "success");
          ctx.ui.notify("Use /plan add <description> to add steps", "info");
          break;

        case "stop":
          planState.enabled = false;
          await savePlan();
          ctx.ui.notify("Plan mode: OFF", "info");
          break;

        case "add": {
          if (!rest.length) {
            ctx.ui.notify("Usage: /plan add <description>", "error");
            return;
          }
          const step = {
            id: generateId(),
            description: rest.join(" "),
            status: "pending" as const,
            timestamp: Date.now(),
          };
          planState.steps.push(step);
          await savePlan();
          ctx.ui.notify(`Added step: ${step.description}`, "success");
          break;
        }

        case "done":
          if (planState.currentStep >= planState.steps.length) {
            ctx.ui.notify("No more steps!", "info");
            return;
          }
          planState.steps[planState.currentStep].status = "completed";
          planState.currentStep++;
          await savePlan();
          ctx.ui.notify(
            `Step completed! ${planState.currentStep}/${planState.steps.length}`,
            "success"
          );
          break;

        case "status": {
          const status = planState.steps
            .map((s, i) => `  ${i + 1}. [${s.status.toUpperCase()}] ${s.description}`)
            .join("\n");
          ctx.ui.notify(`Plan Status:\n${status || "No steps yet"}`, "info");
          break;
        }

        case "clear":
          planState.steps = [];
          planState.currentStep = 0;
          await savePlan();
          ctx.ui.notify("Plan cleared", "info");
          break;

        default:
          ctx.ui.notify(
            "Plan Mode Commands:\n" +
              "  /plan start  - Enable plan mode\n" +
              "  /plan stop   - Disable plan mode\n" +
              "  /plan add <desc> - Add step\n" +
              "  /plan done   - Mark current step done\n" +
              "  /plan status - Show progress\n" +
              "  /plan clear  - Clear all steps",
            "info"
          );
      }
    },
  });

  // Gate destructive tool calls when plan mode is active
  pi.on("tool_call", async (event, ctx) => {
    if (!planState.enabled) return;
    const destructive = ["write", "edit", "bash", "delete"];
    if (!destructive.includes(event.toolName)) return;

    const current = planState.steps[planState.currentStep]?.description || "current step";
    const approved = await ctx.ui.confirm(
      "Plan Mode",
      `Execute ${event.toolName}?  (${current})`
    );
    if (!approved) {
      return { block: true, reason: "Plan mode requires approval" };
    }
  });

  pi.on("session_start", async (_event, ctx) => {
    const candidates = [".specify/scratch/PLAN.md", "PLAN.md"];
    for (const p of candidates) {
      try {
        await fs.access(p);
        planState.planFile = p;
        ctx.ui.notify(`Previous plan found at ${p}. Use /plan status to review.`, "info");
        return;
      } catch {}
    }
  });
}

import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
import { Type } from "typebox";
import { spawn, execSync } from "node:child_process";

function execTmux(args: string[]): Promise<{ stdout: string; stderr: string; code: number }> {
  return new Promise((resolve) => {
    const proc = spawn("tmux", args, { stdio: ["pipe", "pipe", "pipe"], windowsHide: true });
    let stdout = "";
    let stderr = "";
    proc.stdout?.on("data", (d) => (stdout += d.toString()));
    proc.stderr?.on("data", (d) => (stderr += d.toString()));
    proc.on("close", (code) =>
      resolve({ stdout: stdout.trim(), stderr: stderr.trim(), code: code || 0 })
    );
    proc.on("error", (err) => resolve({ stdout: "", stderr: err.message, code: -1 }));
  });
}

function hasTmux(): boolean {
  try {
    execSync("which tmux", { stdio: "ignore" });
    return true;
  } catch {
    return false;
  }
}

export default function (pi: ExtensionAPI) {
  const NOT_INSTALLED = {
    content: [{ type: "text" as const, text: "Error: tmux not installed" }],
    isError: true,
    details: {},
  };

  // ============== Tools (LLM-callable) ==============

  pi.registerTool({
    name: "tmux_new_session",
    label: "Tmux: New Session",
    description: "Create a detached tmux session running a command. Use for long jobs.",
    parameters: Type.Object({
      name: Type.String({ description: "Session name" }),
      command: Type.String({ description: "Command to run" }),
      cwd: Type.Optional(Type.String({ description: "Working directory" })),
    }),
    async execute(_id, params) {
      if (!hasTmux()) return NOT_INSTALLED;
      const args = ["new-session", "-d", "-s", params.name];
      if (params.cwd) args.unshift("-c", params.cwd);
      args.push(params.command);
      const r = await execTmux(args);
      if (r.code !== 0)
        return { content: [{ type: "text", text: `Error: ${r.stderr}` }], isError: true, details: {} };
      return {
        content: [{ type: "text", text: `✓ Session '${params.name}' started\n$ ${params.command}` }],
        details: { session: params.name },
      };
    },
  });

  pi.registerTool({
    name: "tmux_capture_pane",
    label: "Tmux: Capture Pane",
    description: "Read the current visible content of a tmux session — use to check on background jobs.",
    parameters: Type.Object({
      session: Type.String({ description: "Session name" }),
      target: Type.Optional(Type.String({ description: "Target pane (default: active)" })),
    }),
    async execute(_id, params) {
      if (!hasTmux()) return NOT_INSTALLED;
      const r = await execTmux(["capture-pane", "-p", "-t", params.target || params.session]);
      if (r.code !== 0)
        return { content: [{ type: "text", text: `Error: ${r.stderr}` }], isError: true, details: {} };
      const lines = r.stdout.split("\n");
      const truncated =
        lines.length > 200 ? lines.slice(-200).join("\n") + "\n... (truncated to last 200 lines)" : r.stdout;
      return {
        content: [{ type: "text", text: `Session: ${params.session}\n\n${truncated}` }],
        details: { session: params.session, lines: lines.length },
      };
    },
  });

  pi.registerTool({
    name: "tmux_send_keys",
    label: "Tmux: Send Keys",
    description: "Send keys/commands to a tmux session.",
    parameters: Type.Object({
      session: Type.String({ description: "Session name" }),
      keys: Type.String({ description: "Keys or command to send" }),
      enter: Type.Optional(Type.Boolean({ description: "Press Enter after sending", default: true })),
    }),
    async execute(_id, params) {
      if (!hasTmux()) return NOT_INSTALLED;
      const args = ["send-keys", "-t", params.session, params.keys];
      if (params.enter !== false) args.push("Enter");
      const r = await execTmux(args);
      if (r.code !== 0)
        return { content: [{ type: "text", text: `Error: ${r.stderr}` }], isError: true, details: {} };
      return { content: [{ type: "text", text: `✓ Sent to '${params.session}': ${params.keys}` }], details: {} };
    },
  });

  pi.registerTool({
    name: "tmux_kill_session",
    label: "Tmux: Kill Session",
    description: "Terminate a tmux session.",
    parameters: Type.Object({
      name: Type.String({ description: "Session name to kill" }),
    }),
    async execute(_id, params) {
      if (!hasTmux()) return NOT_INSTALLED;
      const r = await execTmux(["kill-session", "-t", params.name]);
      if (r.code !== 0)
        return { content: [{ type: "text", text: `Error: ${r.stderr}` }], isError: true, details: {} };
      return { content: [{ type: "text", text: `✓ Killed '${params.name}'` }], details: {} };
    },
  });

  // ============== Slash command (user-facing) ==============

  pi.registerCommand("tmux", {
    description: "Manage tmux sessions for background work",
    handler: async (args, ctx) => {
      if (!hasTmux()) {
        ctx.ui.notify("tmux not installed", "error");
        return;
      }

      const [cmd, sessionName, ...rest] = args?.split(" ") || [];

      switch (cmd) {
        case "list": {
          const r = await execTmux(["list-sessions"]);
          ctx.ui.notify(r.stdout || "No active sessions", "info");
          break;
        }
        case "new": {
          if (!sessionName) {
            ctx.ui.notify("Usage: /tmux new <name> [command]", "error");
            return;
          }
          const command = rest.join(" ") || "bash";
          await execTmux(["new-session", "-d", "-s", sessionName, command]);
          ctx.ui.notify(`✓ Created '${sessionName}'  $ ${command}`, "success");
          break;
        }
        case "attach": {
          if (!sessionName) {
            ctx.ui.notify("Usage: /tmux attach <name>", "error");
            return;
          }
          await execTmux(["attach-session", "-t", sessionName]);
          break;
        }
        case "kill": {
          if (!sessionName) {
            ctx.ui.notify("Usage: /tmux kill <name>", "error");
            return;
          }
          await execTmux(["kill-session", "-t", sessionName]);
          ctx.ui.notify(`✓ Killed '${sessionName}'`, "success");
          break;
        }
        case "send": {
          if (!sessionName || !rest.length) {
            ctx.ui.notify("Usage: /tmux send <name> <command>", "error");
            return;
          }
          await execTmux(["send-keys", "-t", sessionName, rest.join(" "), "Enter"]);
          ctx.ui.notify(`✓ Sent to '${sessionName}'`, "success");
          break;
        }
        case "capture": {
          if (!sessionName) {
            ctx.ui.notify("Usage: /tmux capture <name>", "error");
            return;
          }
          const r = await execTmux(["capture-pane", "-p", "-t", sessionName]);
          ctx.ui.notify(r.stdout || "Empty session", "info");
          break;
        }
        default:
          ctx.ui.notify(
            "Tmux Commands:\n" +
              "  /tmux list                 - List sessions\n" +
              "  /tmux new <name> [cmd]     - Create detached session\n" +
              "  /tmux attach <name>        - Attach (exits pi temporarily)\n" +
              "  /tmux send <name> <cmd>    - Send command to session\n" +
              "  /tmux capture <name>       - Print pane content\n" +
              "  /tmux kill <name>          - Kill session",
            "info"
          );
      }
    },
  });

  pi.on("session_start", async (_event, ctx) => {
    if (!hasTmux()) return;
    const r = await execTmux(["list-sessions"]);
    if (r.stdout) {
      const count = r.stdout.split("\n").length;
      ctx.ui.notify(`tmux: ${count} active session(s)`, "info");
    }
  });
}

import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
import { spawn } from "node:child_process";

function notifyDesktop(title: string, body: string) {
  // Linux: notify-send (libnotify) — most distros / i3 / GNOME / KDE
  try {
    spawn("notify-send", ["-a", "pi", "-t", "5000", title, body], { stdio: "ignore", detached: true }).unref();
    return;
  } catch {}
  // macOS fallback
  try {
    spawn("osascript", ["-e", `display notification "${body}" with title "${title}"`], {
      stdio: "ignore",
      detached: true,
    }).unref();
  } catch {}
}

function osc777(title: string, body: string) {
  // OSC 777 — terminals that support it (alacritty, foot, ghostty, kitty when configured)
  try {
    process.stdout.write(`\x1b]777;notify;${title};${body}\x07`);
  } catch {}
}

export default function (pi: ExtensionAPI) {
  let lastToolStart = 0;
  const LONG_TASK_MS = 10_000;

  pi.on("tool_execution_start", async (event) => {
    if (["bash", "write"].includes(event.toolName)) {
      lastToolStart = Date.now();
    }
  });

  pi.on("tool_execution_end", async (event) => {
    if (lastToolStart && Date.now() - lastToolStart > LONG_TASK_MS) {
      const duration = Math.round((Date.now() - lastToolStart) / 1000);
      const title = "pi: long task done";
      const body = `${event.toolName ?? "tool"} took ${duration}s`;
      osc777(title, body);
      notifyDesktop(title, body);
    }
    lastToolStart = 0;
  });

  pi.on("agent_end", async (_event, ctx) => {
    if (!ctx.hasUI) return;
    const title = "pi";
    const body = "Ready for next command";
    osc777(title, body);
    notifyDesktop(title, body);
  });
}
